not1 = float (input("escreva a primeira nota: ")) #aqui eu declarei a variavel e seu tipo, depois pedi pra inserir um valor, assim como as demais
not2 = float (input ("escreva a segunda nota: "))#aqui eu declarei a variavel e seu tipo , depois pedi pra inserir um valor
not3 = float (input ("escreva a terceira nota: "))#aqui eu declarei a variavel e seu tipo , depois pedi pra inserir um valor

media = (not1+not2+not3) /3 #aqui eu crio uma variavel media para dizer que ela tem o valor das 3 variaveis somadas divididas por 3, os parenteses são por regras matemáticas comuns
print ("A média é:",media) #aqui eu faço um comando pra aparecer na tela a variavel e os textos que fiz